    <FormField label={label} hint={hint ?? counter} error={error} required={required} className={className}>
      {(id) => (
        <textarea
          id={id}
          rows={rows}
          maxLength={maxLength}
          value={value}
          aria-invalid={Boolean(error)}
          className={fieldClasses(error, 'resize-y py-2.5 leading-relaxed')}
          {...rest}
        />
      )}
    </FormField>
  )
}
